Account.ready.then(async user=>{
 const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let items=[],completed=false;const discarded=new Map(),busy=new Set();let leaving=false;
 const modes={reviewer:'Review',exam:'Exam',case_scenarios:'Case scenarios'};
 const trash='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/></svg>';
 function render(){const term=$('attempt-search').value.trim().toLowerCase(),mode=$('attempt-mode').value,subject=$('attempt-subject').value,days=Number($('attempt-date').value);$('count-progress').textContent=items.filter(a=>!a.result&&!discarded.has(a.id)).length;$('count-completed').textContent=items.filter(a=>a.result).length;$('tab-progress').setAttribute('aria-pressed',String(!completed));$('tab-completed').setAttribute('aria-pressed',String(completed));const rows=items.filter(a=>Boolean(a.result)===completed&&(!mode||a.mode===mode)&&(!subject||a.subjects.includes(subject))&&(!days||Date.parse(a.last_activity)>=Date.now()-days*86400000)&&(a.subjects.join(' ')+' '+a.topics.join(' ')).toLowerCase().includes(term));$('history').innerHTML=rows.map(a=>{const name=a.subjects.filter(Boolean).join(', ')||'Mixed subjects',topic=a.topics.filter(Boolean).join(', ')||'All topics';if(discarded.has(a.id))return `<div class="discarded-row"><div><p>Attempt discarded</p><small>${esc(name)} · ${esc(modes[a.mode])}</small></div><button class="secondary" data-undo="${esc(a.id)}" ${busy.has(a.id)?'disabled':''}>Undo</button></div>`;const elapsed=AttemptUI.duration(Math.max(0,Date.parse(a.submitted||new Date().toISOString())-Date.parse(a.started)));return `<article class="attempt-card"><span class="attempt-mode" data-mode="${esc(a.mode)}">${esc(modes[a.mode]||a.mode)}</span><div><h2>${esc(name)}</h2><p>${esc(topic)}${a.mode==='case_scenarios'?' · '+a.scenario_count+' scenario'+(a.scenario_count===1?'':'s'):''}</p></div><div class="attempt-progress">${a.result?`<strong>${a.result.total} / ${a.result.maximum} points</strong><p>${a.questions} questions</p>`:`<strong>${a.answered} of ${a.questions} answered</strong><progress value="${a.answered}" max="${a.questions}" aria-label="Answer progress"></progress>`}<p>Elapsed ${esc(elapsed)} · ${a.result?'Completed':'Last activity'} ${esc(new Date(a.result?a.submitted:a.last_activity).toLocaleString())}</p></div><div class="attempt-actions">${a.result?`<button class="secondary" data-attempt="${esc(a.id)}">View results</button>`:`<a class="primary" href="/?set=1&attempt=${encodeURIComponent(a.id)}">Resume</a><button class="discard-attempt" data-discard="${esc(a.id)}" aria-label="Discard unfinished ${esc(modes[a.mode])} attempt: ${esc(name)}" title="Discard unfinished attempt" ${busy.has(a.id)?'disabled':''}>${trash}</button>`}</div></article>`}).join('')||'<div class="empty-attempts">'+(completed?'No completed attempts match these filters.':'No unfinished attempts match these filters.')+' <a href="/sets.html">Start a new session</a></div>';
 document.querySelectorAll('[data-discard]').forEach(b=>b.onclick=()=>discard(b.dataset.discard));document.querySelectorAll('[data-undo]').forEach(b=>b.onclick=()=>undo(b.dataset.undo));document.querySelectorAll('[data-attempt]').forEach(b=>b.onclick=()=>showResult(b.dataset.attempt));}
 function finalize(id,token){return fetch('/api/attempts/discard',{method:'POST',keepalive:true,headers:{'Content-Type':'application/json','X-Quiz-Admin':'1'},body:JSON.stringify({id,token,action:'finalize',account_id:user.id})}).catch(()=>{});}
 async function discard(id){if(busy.has(id))return;busy.add(id);render();const token=crypto.randomUUID();try{await Account.request('/api/attempts/discard',{id,token,action:'discard'});discarded.set(id,token);$('history-status').textContent='Attempt discarded. You can undo until you leave or refresh this page.';if(leaving)finalize(id,token);}catch(e){$('history-status').textContent=e.message}finally{busy.delete(id);render()}}
 async function undo(id){if(busy.has(id))return;const token=discarded.get(id);if(!token)return;busy.add(id);render();try{await Account.request('/api/attempts/discard',{id,token,action:'undo'});discarded.delete(id);$('history-status').textContent='Attempt restored. Your saved progress is unchanged.';}catch(e){$('history-status').textContent=e.message}finally{busy.delete(id);render()}}
 window.addEventListener('pagehide',()=>{leaving=true;for(const [id,token] of discarded)finalize(id,token)});window.addEventListener('pageshow',e=>{if(e.persisted)location.reload()});
 for(const id of ['attempt-mode','attempt-subject','attempt-date'])$(id).onchange=render;$('attempt-search').oninput=render;$('tab-progress').onclick=()=>{completed=false;render()};$('tab-completed').onclick=()=>{completed=true;render()};$('reset-attempt-filters').onclick=()=>{for(const id of ['attempt-mode','attempt-subject','attempt-date','attempt-search'])$(id).value='';render()};
 async function showResult(id){try{
 const a=await Account.request('/api/attempt?id='+encodeURIComponent(id));const el=document.getElementById('attempt-detail');el.hidden=false;
 el.innerHTML='<h2>Saved result</h2>'+(a.mode==='case_scenarios'?AttemptUI.scenarioSummary(a.questions,a.result):'')+AttemptUI.legend()+'<nav class="attempt-map" aria-label="Saved question scores">'+a.result.items.map((r,i)=>`<a href="#saved-question-${i}" class="${AttemptUI.color(r)}" aria-label="Question ${a.questions[i].display_label||i+1}: ${AttemptUI.label(r)}" title="${AttemptUI.label(r)}">${a.questions[i].display_label||i+1}</a>`).join('')+'</nav>'+a.questions.map((q,i)=>{const r=a.result.items[i];return `<div class="history-item" id="saved-question-${i}"><h3>Question ${a.questions[i].display_label||i+1} · ${esc(q.display_code||q.id)} · revision ${q.revision}</h3>${q.case?`<details ${i===0||a.questions[i-1].case_id!==q.case_id?'open':''}><summary>Case ${esc(q.case_id)}: ${esc(q.case.title)}</summary><div class="formatted-text">${RichText.render('History:\n'+q.case.history+'\n\nPhysical examination:\n'+q.case.examination+'\n\nLaboratory findings:\n'+q.case.laboratory)}</div></details>`:''}${q.additional_findings?`<h4>Additional findings before this question</h4><div class="formatted-text">${RichText.render(q.additional_findings)}</div>`:''}<div class="formatted-text">${RichText.render(q.text)}</div><p>Your response: ${esc(r.blank?'Unanswered':Array.isArray(r.answer)?r.answer.map(id=>id+'. '+(q.choices.find(c=>c.id===id)?.text||'')).join('; '):r.answer)}</p>${q.choice_scores?`<p>Option scores: ${esc(Object.entries(q.choice_scores).map(([id,score])=>id+': '+score).join(' · '))}</p>`:''}<p>Full-credit answer: ${esc(q.type==='range'?q.lower+'–'+q.upper:q.choices.filter(c=>q.accepted.includes(c.id)).map(c=>c.id+'. '+c.text).join('; '))}</p>${q.explanation?`<div><strong>Explanation:</strong> ${RichText.render(q.explanation)}</div>`:''}${RichText.explanationImage(q)}<strong class="${AttemptUI.color(r)}">${r.score} / ${r.maximum} points${r.blank?' · Unanswered':''}</strong></div>`}).join('');el.scrollIntoView({behavior:'smooth'}); }catch(e){$('history-status').textContent=e.message}}
 try{items=await Account.request('/api/attempts');$('attempt-subject').replaceChildren(new Option('All subjects',''),...[...new Set(items.flatMap(a=>a.subjects).filter(Boolean))].sort().map(s=>new Option(s,s)));const requested=new URLSearchParams(location.search).get('attempt');if(requested&&items.some(a=>a.id===requested&&a.result))completed=true;render();if(requested&&completed)await showResult(requested);}catch(e){$('history-status').textContent=e.message}
}).catch(()=>{});
